const DASH = window.DASHBOARD_DATA || {};
const BALANCE_INITIAL = Number(DASH.balanceInitial || 0);
const MAX_FUNDED_HISTORICAL = Number(DASH.maxFundedHistorical || 0);
const accounts = Array.isArray(DASH.accounts) ? DASH.accounts : [];
const moves = Array.isArray(DASH.moves) ? DASH.moves : [];

const money = v => '$' + Math.abs(v).toLocaleString('en-US',{maximumFractionDigits:2});
const signedMoney = v => (v < 0 ? '-$' : '$') + Math.abs(v).toLocaleString('en-US',{maximumFractionDigits:2});
const k = v => '$' + (v/1000).toLocaleString('en-US',{maximumFractionDigits:1}).replace('.0','') + 'K';
const pct = v => (isFinite(v) ? v : 0).toFixed(1) + '%';
const periodMatch = (date,p) => p === 'total' || (date && date.slice(0,7) === p);

function render(p){
  const monthMode = p !== 'total';
  const fm = moves.filter(m => periodMatch(m.date,p));
  const fa = accounts.filter(a => periodMatch(a.date,p));
  const scopedAccounts = monthMode ? fa : accounts;

  const spent = -fm.filter(m => m.amount < 0).reduce((s,m) => s + m.amount,0);
  const paid = fm.filter(m => m.type === 'Payout' && m.amount > 0).reduce((s,m) => s + m.amount,0);
  const internalFunds = fm.filter(m => m.type === 'Ajuste' && m.amount > 0).reduce((s,m) => s + m.amount,0);
  const net = paid - spent;

  const liveAcc = scopedAccounts.filter(a => a.status === 'Live');
  const fundedEverAcc = scopedAccounts.filter(a => a.everLive === true);
  const challengeAcc = scopedAccounts.filter(a => a.status === 'Challenge');
  const pendingAcc = scopedAccounts.filter(a => a.status === 'Pendiente');

  const capitalLive = liveAcc.reduce((s,a) => s + a.size,0);
  const capitalChallenge = challengeAcc.reduce((s,a) => s + a.size,0);
  const capitalPending = pendingAcc.reduce((s,a) => s + a.size,0);
  const capitalBought = scopedAccounts.reduce((s,a) => s + a.size,0);

  const fundingRatio = scopedAccounts.length ? fundedEverAcc.length / scopedAccounts.length * 100 : 0;
  const ratioAccounts = scopedAccounts.length ? liveAcc.length / scopedAccounts.length * 100 : 0;
  const bal = BALANCE_INITIAL + internalFunds + net;

  document.getElementById('balance').textContent = money(bal);
  document.getElementById('spent').textContent = money(spent);
  document.getElementById('paid').textContent = money(paid);
  document.getElementById('net').textContent = signedMoney(net);
  document.getElementById('net').className = 'value ' + (net >= 0 ? 'green' : 'red');

  document.getElementById('funded').textContent = k(capitalLive);
  document.getElementById('liveCount').textContent = liveAcc.length + ' cuentas Live';
  document.getElementById('fundingRatio').textContent = pct(fundingRatio);
  document.getElementById('fundingSmall').textContent = fundedEverAcc.length + ' fondeadas / ' + scopedAccounts.length + ' compradas';

  document.getElementById('capitalLive').textContent = k(capitalLive);
  document.getElementById('capitalChallenge').textContent = k(capitalChallenge);
  const pendingEl = document.getElementById('capitalPending');
  if (pendingEl) pendingEl.textContent = k(capitalPending);
  document.getElementById('ratioAccounts').textContent = pct(ratioAccounts);
  document.getElementById('donutNumber').textContent = Math.round(fundingRatio) + '%';
  document.getElementById('donut').style.setProperty('--funding',Math.min(100,Math.max(0,fundingRatio)) + '%');

  document.getElementById('breakeven').textContent = money(Math.max(0,spent-paid));
  document.getElementById('recovery').textContent = spent ? pct(paid/spent*100) : '0%';
  document.getElementById('roi').textContent = spent ? pct(net/spent*100) : '0%';
  document.getElementById('roi').className = 'value ' + (net >= 0 ? 'green' : 'red');

  const monthLabel = p === '2026-09' ? 'Septiembre 2026' : p === '2026-08' ? 'Agosto 2026' : 'Total';
  document.getElementById('subtitle').textContent = monthMode ? 'Vista mensual · ' + monthLabel : 'Situación actual · ' + (DASH.updatedAt || 'sin fecha');
  document.getElementById('balanceSmall').textContent = monthMode ? 'Incluye aportes internos registrados en el periodo' : 'Fondos internos aportados ' + money(BALANCE_INITIAL + internalFunds);

  const maxChart = Math.max(800,spent,paid);
  const y = v => 234 - (Math.min(maxChart,v)/maxChart)*200;
  const sy = y(spent), py = y(paid);
  document.getElementById('spendLine').setAttribute('points',`70,234 650,${sy}`);
  document.getElementById('spendDot').setAttribute('cy',sy);
  document.getElementById('paidLine').setAttribute('points',`70,234 650,${py}`);
  document.getElementById('paidDot').setAttribute('cy',py);
  document.getElementById('spendLabel').textContent = money(spent);
  document.getElementById('spendLabel').setAttribute('y',Math.max(20,sy-12));
  document.getElementById('paidLabel').textContent = money(paid);
  document.getElementById('paidLabel').setAttribute('y',Math.max(20,py-12));

  document.getElementById('chartNote').textContent = monthMode
    ? 'Los movimientos históricos anteriores no tienen fecha exacta y solo aparecen en TOTAL. Los movimientos con fecha registrada aparecen en su mes.'
    : 'Los aportes de fondos internos aumentan la caja disponible, pero no se contabilizan como payout ni como beneficio.';

  const props = ['Breakout','Orion','BitFunded','Propr'];
  document.getElementById('firmGrid').innerHTML = props.map(prop => {
    const aa = scopedAccounts.filter(a => a.prop === prop);
    const mm = fm.filter(m => m.prop === prop);
    const sp = -mm.filter(m => m.amount < 0).reduce((s,m) => s + m.amount,0);
    const pa = mm.filter(m => m.type === 'Payout' && m.amount > 0).reduce((s,m) => s + m.amount,0);
    const nl = pa - sp;
    const lv = aa.filter(a => a.status === 'Live').reduce((s,a) => s + a.size,0);
    return `<div class="firm-card"><div class="firm-head"><div><div class="firm-name">${prop}</div><div class="small">${aa.length} ${aa.length===1?'cuenta':'cuentas'}</div></div><div class="${nl>=0?'green':'red'}">${signedMoney(nl)} neto</div></div><div class="firm-metrics"><div><span class="label">Gastado</span><strong class="cyan">${money(sp)}</strong></div><div><span class="label">Payouts</span><strong class="pink">${money(pa)}</strong></div><div><span class="label">Live</span><strong class="green">${k(lv)}</strong></div></div></div>`;
  }).join('');

  const shown = scopedAccounts;
  document.getElementById('accountList').innerHTML = shown.length ? shown.map(a => {
    const badgeClass = a.status === 'Live' ? 'green' : a.status === 'Challenge' ? 'amber' : a.status === 'Perdida' ? 'red' : 'cyan';
    const badgeText = a.status === 'Live' ? 'LIVE' : a.status === 'Challenge' ? 'CHALLENGE' : a.status === 'Perdida' ? 'PERDIDA' : 'PENDIENTE';
    return `<div class="account"><div><div class="name">${a.name}</div><div class="meta">${a.meta}</div><span class="badge ${badgeClass}"><span class="dot"></span>${badgeText}</span></div><div class="amount">${k(a.size)}</div></div>`;
  }).join('') : `<div class="note">No hay cuentas con fecha de compra registrada en este mes. El histórico anterior se conserva en TOTAL.</div>`;

  const footer = document.querySelector('.footer');
  if (footer) footer.textContent = 'PROP FIRMS CONTROL · V4 · DATOS MANUALES · ' + (DASH.updatedAt || 'sin fecha');

  const maxFundedEl = document.querySelector('.mini .card.greenLine:last-child .value');
  if (maxFundedEl) maxFundedEl.textContent = k(MAX_FUNDED_HISTORICAL);
}

document.getElementById('period').addEventListener('change',e => render(e.target.value));
render('total');
